namespace Ara {
 // Public OAuth client: no application secret and no access token crosses the UI bridge.
 public sealed class NotionHub {
  const string Origin="https://mcp.notion.com";
  readonly string file;readonly object gate=new object();Dictionary<string,object> vault;string session="",message="";bool pending;long serial;
  public Func<string,string,string,string,Dictionary<string,object>> Transport;public NotionDiaryAuto Automatic;
  public NotionHub(string dataFile){file=Path.Combine(Path.GetDirectoryName(dataFile),"notion-oauth.bin");vault=new Dictionary<string,object>();if(File.Exists(file))try{vault=JsonMap.Read(Encoding.UTF8.GetString(ProtectedData.Unprotect(File.ReadAllBytes(file),null,DataProtectionScope.CurrentUser)));}catch{message="이 기기의 노션 연결을 다시 진행해 주세요.";}}
  void Save(){Directory.CreateDirectory(Path.GetDirectoryName(file));byte[] bytes=ProtectedData.Protect(Encoding.UTF8.GetBytes(JsonMap.Write(vault)),null,DataProtectionScope.CurrentUser);string tmp=file+".tmp";File.WriteAllBytes(tmp,bytes);if(File.Exists(file))File.Replace(tmp,file,null);else File.Move(tmp,file);}
  static string S(Dictionary<string,object> d,string k){return JsonMap.Str(d,k);}
  static long Epoch(){return (long)(DateTime.UtcNow-new DateTime(1970,1,1)).TotalSeconds;}
  static Dictionary<string,string> Query(string query){var result=new Dictionary<string,string>();foreach(string part in query.TrimStart('?').Split('&')){var pair=part.Split(new[]{'='},2);if(pair.Length==2)result[Uri.UnescapeDataString(pair[0])]=Uri.UnescapeDataString(pair[1]);}return result;}
  static string Random(){byte[] b=new byte[32];using(var r=RandomNumberGenerator.Create())r.GetBytes(b);return B64(b);}
  static string B64(byte[] b){return Convert.ToBase64String(b).TrimEnd('=').Replace('+','-').Replace('/','_');}
  static string Form(Dictionary<string,object> d){return string.Join("&",d.Select(x=>Uri.EscapeDataString(x.Key)+"="+Uri.EscapeDataString(Convert.ToString(x.Value))));}
  public static bool AllowedTool(string name){string n=name.Replace('_','-');return new[]{"fetch","search","get-self","get-tool-access","list-private-pages","list-shared-pages","list-recent-pages","create-pages","create-database","create-view"}.Any(x=>n==x||n=="notion-"+x);}
  public static void ValidatePageCreate(Dictionary<string,object> args){var pages=JsonMap.Items(args,"pages");if(pages.Length!=1)throw new InvalidDataException("새 페이지는 한 번에 하나씩 만듭니다.");var page=JsonMap.Map(pages[0]);var props=JsonMap.Child(page,"properties");object title;if(page.Count!=1||props.Count!=1||!props.TryGetValue("title",out title)||!(title is string)||((string)title).Trim().Length==0||((string)title).Length>80)throw new InvalidDataException("새 페이지에는 1~80자의 제목만 지정할 수 있습니다.");var parent=JsonMap.Child(args,"parent");if(parent.Count==0){if(S(args,"creation_mode")!="draft")throw new InvalidDataException("개인 공간 위치를 확인해 주세요.");}else{Guid id;if(parent.Count!=1||!Guid.TryParse(S(parent,"page_id"),out id)||args.ContainsKey("creation_mode"))throw new InvalidDataException("일반 페이지 아래에만 만들 수 있습니다.");}if(S(args,"allow_async")=="True")throw new InvalidDataException("페이지 생성 결과를 바로 확인해야 합니다.");}
  public static Dictionary<string,object> ParseRpc(string raw,long id){if(raw.TrimStart().StartsWith("{")){var item=JsonMap.Read(raw);if(S(item,"id")!=id.ToString())throw new InvalidDataException("노션 응답 번호가 일치하지 않습니다.");return item;}foreach(var line in raw.Split('\n'))if(line.StartsWith("data:")){var text=line.Substring(5).Trim();if(text=="[DONE]")continue;try{var item=JsonMap.Read(text);if(S(item,"id")==id.ToString())return item;}catch{}}throw new InvalidDataException("노션 응답을 읽지 못했습니다. 다시 시도해 주세요.");}
  Dictionary<string,object> Http(string path,string method,string body,string type,string token){
   if(Transport!=null)return Transport(method,path,body,token);
   if(!path.StartsWith("/")||path.StartsWith("//")||path.Contains(".."))throw new InvalidDataException("노션 주소가 올바르지 않습니다.");
   ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var req=(HttpWebRequest)WebRequest.Create(Origin+path);req.Method=method;req.UserAgent="ARA-Daily-OS/2.0";req.Accept="application/json, text/event-stream";req.Timeout=45000;req.ReadWriteTimeout=45000;req.AllowAutoRedirect=false;
   if(!string.IsNullOrEmpty(token))req.Headers["Authorization"]="Bearer "+token;if(path=="/mcp"){req.Headers["MCP-Protocol-Version"]="2025-03-26";if(session.Length>0)req.Headers["Mcp-Session-Id"]=session;}
   if(body!=null){req.ContentType=type;byte[] bytes=Encoding.UTF8.GetBytes(body);req.ContentLength=bytes.Length;using(var output=req.GetRequestStream())output.Write(bytes,0,bytes.Length);}
   try{using(var response=(HttpWebResponse)req.GetResponse()){if(path=="/mcp"&&!string.IsNullOrEmpty(response.Headers["Mcp-Session-Id"]))session=response.Headers["Mcp-Session-Id"];using(var stream=response.GetResponseStream()){string raw=NotionService.ReadBounded(stream,2000000);return raw.Length==0?new Dictionary<string,object>():path=="/mcp"?ParseRpc(raw,serial):JsonMap.Read(raw);}}}catch(WebException e){var response=e.Response as HttpWebResponse;int code=response==null?0:(int)response.StatusCode;if(response!=null)response.Dispose();if(code==401)throw new UnauthorizedAccessException("노션 연결이 만료되었습니다. 다시 연결해 주세요.");throw new InvalidOperationException(code==429?"노션 요청이 많습니다. 잠시 후 다시 시도해 주세요.":"노션 연결을 완료하지 못했습니다 ("+code+"). 인터넷 연결을 확인해 주세요.");}
  }
  Dictionary<string,object> Token(Dictionary<string,object> form){return Http("/token","POST",Form(form),"application/x-www-form-urlencoded",null);}
  void StoreTokens(Dictionary<string,object> tokens){if(S(tokens,"access_token").Length<10)throw new InvalidDataException("노션 로그인 응답에 연결 정보가 없습니다.");foreach(var pair in tokens)vault[pair.Key]=pair.Value;object lifetime;vault["expires_at"]=Epoch()+(tokens.TryGetValue("expires_in",out lifetime)?Convert.ToInt64(lifetime):3600);Save();session="";}
  string Access(){if(S(vault,"access_token").Length==0)throw new InvalidOperationException("먼저 노션 연결을 눌러 주세요.");object expiry;if(vault.TryGetValue("expires_at",out expiry)&&Convert.ToInt64(expiry)<Epoch()+60){try{StoreTokens(Token(JsonMap.Obj("grant_type","refresh_token","refresh_token",S(vault,"refresh_token"),"client_id",S(vault,"client_id"))));}catch(UnauthorizedAccessException){vault.Remove("access_token");Save();throw;}}return S(vault,"access_token");}
  Dictionary<string,object> Rpc(string method,object args){long id=++serial;var value=Http("/mcp","POST",JsonMap.Write(JsonMap.Obj("jsonrpc","2.0","id",id,"method",method,"params",args)),"application/json",Access());if(value.ContainsKey("error"))throw new InvalidOperationException("노션 요청 실패: "+S(JsonMap.Child(value,"error"),"message"));return JsonMap.Child(value,"result");}
  public object Request(Dictionary<string,object> input){lock(gate){string op=S(input,"op");if(op=="status")return JsonMap.Obj("connected",S(vault,"access_token").Length>0,"pending",pending,"message",message,"workspace",S(vault,"workspace_name"),"target",vault.ContainsKey("target")?vault["target"]:null,"destination",vault.ContainsKey("destination")?vault["destination"]:null);
    if(op=="auto-status")return Automatic==null?JsonMap.Obj("enabled",true,"pending",0,"error","PC 자동 저장 준비 중"):Automatic.Status();
    if(op=="auto-enable"){if(Automatic==null)throw new InvalidOperationException("자동 저장이 준비되지 않았습니다.");Automatic.SetEnabled(S(input,"enabled")=="True");return Automatic.Status();}
    if(op=="auto-sync"){if(Automatic!=null)Automatic.RetryNow();return JsonMap.Obj("queued",true);}
    if(op=="connect"){Begin();return JsonMap.Obj("pending",true);}
    if(op=="disconnect"){if(pending)throw new InvalidOperationException("로그인 창을 완료하거나 잠시 뒤 다시 시도해 주세요.");vault.Clear();Save();session="";return JsonMap.Obj("connected",false);}
    if(op=="target"){var target=JsonMap.Child(input,"target");Guid id;if(!Guid.TryParse(S(target,"id"),out id))throw new InvalidDataException("노션 데이터베이스 ID를 확인해 주세요.");vault["target"]=target;Save();if(Automatic!=null)Automatic.Poke();return JsonMap.Obj("saved",true);}
    if(op=="destination"){var dest=JsonMap.Child(input,"destination");string id=NotionDaily.Id(S(dest,"id"));var oldTarget=JsonMap.Child(vault,"target");if(oldTarget.Count>0&&id!=S(oldTarget,"parentId"))vault.Remove("target");vault["destination"]=JsonMap.Obj("id",id,"title",S(dest,"title"));Save();return JsonMap.Obj("saved",true);}
    if(op=="daily"||op=="daily-reset"||op=="inline"||op=="diary"){if(op=="diary"&&!NotionDiary.Active(input))return JsonMap.Obj("skipped",true,"reason","no_activity");var dailyTarget=JsonMap.Child(vault,"target");if(dailyTarget.Count==0)throw new InvalidOperationException("저장할 하루 기록 DB를 먼저 지정해 주세요.");if(op=="inline"){var result=NotionDaily.Inline(dailyTarget,DailyCall(),value=>{dailyTarget["inlinePending"]=value;if(!value)dailyTarget["inlineParentId"]=S(dailyTarget,"parentId");Save();});dailyTarget["inlineParentId"]=S(dailyTarget,"parentId");dailyTarget["inlinePending"]=false;dailyTarget["inlineRevision"]=2;Save();return result;}if(op=="diary"&&S(dailyTarget,"parentId").Length>0&&S(dailyTarget,"inlineRevision")!="2")Request(JsonMap.Obj("op","inline"));string day=NotionDaily.Date(input),dayKey=S(dailyTarget,"id")+"|"+day;var journal=JsonMap.Child(vault,"dailyPending");vault["dailyPending"]=journal;if(op=="daily-reset"){journal.Remove(dayKey);Save();return JsonMap.Obj("reset",true);}var writer=DailyCall();Action<bool> mark=value=>{if(value)journal[dayKey]=true;else journal.Remove(dayKey);Save();};return op=="diary"?NotionDiary.Save(input,dailyTarget,S(journal,dayKey)=="True",writer,mark):NotionDaily.Save(input,dailyTarget,S(journal,dayKey)=="True",writer,mark);}
    if(op!="tools"&&op!="call")throw new InvalidDataException("지원하지 않는 노션 연결 요청입니다.");
    Access();if(session.Length==0){Rpc("initialize",JsonMap.Obj("protocolVersion","2025-03-26","capabilities",JsonMap.Obj(),"clientInfo",JsonMap.Obj("name","ARA Daily OS","version","2.0")));Http("/mcp","POST",JsonMap.Write(JsonMap.Obj("jsonrpc","2.0","method","notifications/initialized")),"application/json",Access());}
    if(op=="tools")return Rpc("tools/list",JsonMap.Obj());string name=S(input,"name");if(!AllowedTool(name))throw new InvalidDataException("이 연결 화면에서 허용하지 않는 노션 작업입니다.");if(name.Replace('_','-')=="notion-create-pages"||name.Replace('_','-')=="create-pages")ValidatePageCreate(JsonMap.Child(input,"arguments"));return Rpc("tools/call",JsonMap.Obj("name",name,"arguments",JsonMap.Child(input,"arguments")));
  }}
  NotionDaily.Call DailyCall(){var tools=JsonMap.Items(JsonMap.Map(Request(JsonMap.Obj("op","tools"))),"tools").Select(JsonMap.Map).ToArray();return(suffix,args)=>{var tool=tools.FirstOrDefault(x=>S(x,"name").Replace('_','-')==suffix||S(x,"name").Replace('_','-')=="notion-"+suffix);if(tool==null)throw new InvalidOperationException("현재 노션 계정에서 "+suffix+" 기능을 사용할 수 없습니다.");return Rpc("tools/call",JsonMap.Obj("name",S(tool,"name"),"arguments",args));};}
  void Begin(){if(pending)throw new InvalidOperationException("이미 노션 로그인 창을 기다리고 있습니다.");var meta=Http("/.well-known/oauth-authorization-server","GET",null,null,null);if(S(meta,"issuer")!=Origin||S(meta,"registration_endpoint")!=Origin+"/register"||S(meta,"authorization_endpoint")!=Origin+"/authorize"||S(meta,"token_endpoint")!=Origin+"/token")throw new InvalidDataException("노션 인증 서버를 확인하지 못했습니다.");
   var listener=new TcpListener(IPAddress.Loopback,0);listener.Start(4);string redirect="http://127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port+"/notion/callback";try{var registered=Http("/register","POST",JsonMap.Write(JsonMap.Obj("client_name","ARA Daily OS","redirect_uris",new[]{redirect},"grant_types",new[]{"authorization_code","refresh_token"},"response_types",new[]{"code"},"token_endpoint_auth_method","none")),"application/json",null);string client=S(registered,"client_id"),state=Random(),verifier=Random();if(client.Length==0)throw new InvalidDataException("노션 앱 등록을 완료하지 못했습니다.");string challenge;using(var hash=SHA256.Create())challenge=B64(hash.ComputeHash(Encoding.ASCII.GetBytes(verifier)));pending=true;message="노션에서 로그인·허용 후 앱으로 돌아와 주세요.";var uri=Origin+"/authorize?"+Form(JsonMap.Obj("response_type","code","client_id",client,"redirect_uri",redirect,"state",state,"code_challenge",challenge,"code_challenge_method","S256","scope","default"));Process.Start(new ProcessStartInfo(uri){UseShellExecute=true});
    new Thread(()=>Callback(listener,redirect,client,state,verifier)){IsBackground=true}.Start();
   }catch{pending=false;listener.Stop();throw;}
  }
  void Callback(TcpListener listener,string redirect,string client,string state,string verifier){DateTime until=DateTime.UtcNow.AddMinutes(5);try{while(DateTime.UtcNow<until){if(!listener.Pending()){Thread.Sleep(150);continue;}using(var socket=listener.AcceptTcpClient()){socket.ReceiveTimeout=3000;socket.SendTimeout=3000;var stream=socket.GetStream();var reader=new StreamReader(stream,Encoding.ASCII,false,1024,true);string first=reader.ReadLine()??"";if(first.Length>8192)continue;var pieces=first.Split(' ');if(pieces.Length!=3||pieces[0]!="GET")continue;var uri=new Uri("http://127.0.0.1"+pieces[1]);if(uri.AbsolutePath!="/notion/callback")continue;var query=Query(uri.Query);if((query.ContainsKey("state")?query["state"]:null)!=state)continue;
      string result="노션 연결을 완료했습니다. ARA 앱으로 돌아가 주세요.";try{if(!string.IsNullOrEmpty((query.ContainsKey("error")?query["error"]:null)))throw new InvalidOperationException("노션 연결을 취소했습니다.");if(string.IsNullOrEmpty((query.ContainsKey("code")?query["code"]:null)))throw new InvalidDataException("노션 로그인 코드를 받지 못했습니다.");lock(gate){var tokens=Token(JsonMap.Obj("grant_type","authorization_code","client_id",client,"redirect_uri",redirect,"code_verifier",verifier,"code",(query.ContainsKey("code")?query["code"]:null)));vault["client_id"]=client;if(S(vault,"workspace_id").Length>0&&S(tokens,"workspace_id").Length>0&&S(vault,"workspace_id")!=S(tokens,"workspace_id")){vault.Remove("target");vault.Remove("destination");vault.Remove("dailyPending");}StoreTokens(tokens);message="노션 연결됨";if(Automatic!=null)Automatic.Poke();}}catch(Exception e){lock(gate)message=e.Message;result="연결을 완료하지 못했습니다. ARA 앱에서 상태를 확인해 주세요.";}byte[] body=Encoding.UTF8.GetBytes("<!doctype html><meta charset=utf-8><title>ARA 노션 연결</title><p>"+result+"</p>");byte[] headers=Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: "+body.Length+"\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n");stream.Write(headers,0,headers.Length);stream.Write(body,0,body.Length);return;}}
    lock(gate)message="로그인 대기 시간이 지났습니다. 다시 연결해 주세요.";
   }catch{lock(gate)message="노션 연결을 완료하지 못했습니다. 다시 연결해 주세요.";}finally{listener.Stop();lock(gate)pending=false;}
  }
 }
}
